package com.learnagent.skill;
import com.learnagent.agent.AgentExecutionTracker;import com.learnagent.quiz.*;import java.util.*;import org.springframework.ai.tool.annotation.*;import org.springframework.stereotype.Component;
@Component public class QuizSkill{private final QuizService service;private final AgentExecutionTracker tracker;public QuizSkill(QuizService service,AgentExecutionTracker tracker){this.service=service;this.tracker=tracker;}@Tool(description="Generate and persist an AI quiz from READY course materials. Requires AI and vector providers.")public QuizResult generateQuiz(@ToolParam(description="Quiz generation request")GenerateQuizInput input){return tracker.execute("Quiz Skill","generateQuiz",()->{Quiz quiz=service.generate(new QuizDtos.GenerateRequest(input.courseId(),input.knowledgePoint(),input.questionCount()));return new QuizResult(quiz.getId(),quiz.getCourseId(),quiz.getTitle(),quiz.getKnowledgePoint(),quiz.getStatus());},value->"Generated quiz: "+value.title());}@Tool(description="Read wrong answers for a course from real submitted quiz records.")public List<WrongAnswerResult> getWrongAnswers(@ToolParam(description="Course ID")UUID courseId){return tracker.execute("Quiz Skill","getWrongAnswers",()->service.getWrongAnswers(courseId).stream().map(x->new WrongAnswerResult(x.quizId(),x.questionId(),x.question(),x.userAnswer(),x.correctAnswer(),x.knowledgePoint())).toList(),values->"Found "+values.size()+" wrong answers");}public record GenerateQuizInput(UUID courseId,String knowledgePoint,Integer questionCount){}public record QuizResult(UUID id,UUID courseId,String title,String knowledgePoint,QuizStatus status){}public record WrongAnswerResult(UUID quizId,UUID questionId,String question,String userAnswer,String correctAnswer,String knowledgePoint){}
}
